import{_ as t,o as s,c as e,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 15 章 自动化工作流：让任务自己跑","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 自动化工作流：让任务自己跑.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 自动化工作流：让任务自己跑.md"}'),o={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 自动化工作流：让任务自己跑.md"};function l(i,a,p,r,d,c){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="第-15-章-自动化工作流-让任务自己跑" tabindex="-1">第 15 章 自动化工作流：让任务自己跑 <a class="header-anchor" href="#第-15-章-自动化工作流-让任务自己跑" aria-label="Permalink to &quot;第 15 章 自动化工作流：让任务自己跑&quot;">​</a></h1><h2 id="_15-1-场景" tabindex="-1">15.1 场景 <a class="header-anchor" href="#_15-1-场景" aria-label="Permalink to &quot;15.1 场景&quot;">​</a></h2><p>有些任务，你已经知道完整的做法，只是不想每次都手动做一遍。这就是自动化该上场的时候：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入（文件/参数）→ 固定步骤 → 输出（产物/结果）</span></span></code></pre></div><p>自动化的本质：<strong>把&quot;你会做&quot;变成&quot;它会自己跑&quot;。</strong></p><h2 id="_15-2-什么样的任务适合自动化" tabindex="-1">15.2 什么样的任务适合自动化 <a class="header-anchor" href="#_15-2-什么样的任务适合自动化" aria-label="Permalink to &quot;15.2 什么样的任务适合自动化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不适合</th></tr></thead><tbody><tr><td>步骤固定、重复执行</td><td>每次需求都不同</td></tr><tr><td>输入输出明确</td><td>需要大量即兴判断</td></tr><tr><td>有明确验收标准</td><td>高风险不可逆操作</td></tr><tr><td>频率高（每周/每天）</td><td>一次性任务</td></tr></tbody></table><p>判断一句话：<strong>&quot;如果这个任务做 10 遍，步骤会一样吗？&quot;</strong> 会 → 值得自动化。</p><h2 id="_15-3-自动化的三层境界" tabindex="-1">15.3 自动化的三层境界 <a class="header-anchor" href="#_15-3-自动化的三层境界" aria-label="Permalink to &quot;15.3 自动化的三层境界&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1 脚本化    ：固定输入 → 脚本 → 固定输出</span></span>
<span class="line"><span>L2 模板化    ：用模板生成不同产物（周报、合同、简报）</span></span>
<span class="line"><span>L3 工作流化  ：多步骤串联 + 异常处理 + 人审节点</span></span></code></pre></div><h2 id="_15-4-案例-周报自动化" tabindex="-1">15.4 案例：周报自动化 <a class="header-anchor" href="#_15-4-案例-周报自动化" aria-label="Permalink to &quot;15.4 案例：周报自动化&quot;">​</a></h2><p><strong>手动版：</strong> 每周五收集数据 → 写周报 → 发送。</p><p><strong>自动化版：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入：本周 git 提交记录 + 项目进度文件</span></span>
<span class="line"><span>步骤：收集 → 按模板生成周报草稿 → 输出到 docs/weekly/</span></span>
<span class="line"><span>人工节点：你审阅 → 确认 → 发布</span></span></code></pre></div><p><strong>指令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把&quot;生成周报&quot;做成可复用流程：我每次只说&quot;生成本周周报&quot;，</span></span>
<span class="line"><span>你就走：读 git log → 读进度文件 → 套模板 → 输出草稿让我审阅。</span></span></code></pre></div><h2 id="_15-5-可靠性的三要素" tabindex="-1">15.5 可靠性的三要素 <a class="header-anchor" href="#_15-5-可靠性的三要素" aria-label="Permalink to &quot;15.5 可靠性的三要素&quot;">​</a></h2><p>自动化最怕&quot;悄悄出错&quot;。三条保命原则：</p><ol><li><strong>留痕</strong>：每次运行都有日志，出问题能回看；</li><li><strong>可验证</strong>：产出有校验（行数、格式、内容检查）；</li><li><strong>人审节点</strong>：重要输出在自动化的最后一站，永远留一个人确认。</li></ol><blockquote><p>自动化的目的不是去掉人，而是<strong>把人从重复劳动里解放出来，去做判断</strong>。</p></blockquote><h2 id="_15-6-自动化与-skill-的区别" tabindex="-1">15.6 自动化与 Skill 的区别 <a class="header-anchor" href="#_15-6-自动化与-skill-的区别" aria-label="Permalink to &quot;15.6 自动化与 Skill 的区别&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill     = 按最佳实践执行一件事（我来做，你在场）</span></span>
<span class="line"><span>自动化     = 固定流程自己跑（我主动跑，你抽查）</span></span></code></pre></div><p>两者结合：<strong>Skill 定义&quot;怎么做对&quot;，自动化定义&quot;什么时候做&quot;。</strong> 详细方法论见第 19 章。</p><h2 id="_15-7-练习" tabindex="-1">15.7 练习 <a class="header-anchor" href="#_15-7-练习" aria-label="Permalink to &quot;15.7 练习&quot;">​</a></h2><ol><li>找出你工作中一个每周都要做的重复任务；</li><li>把它的步骤写成清单，让我评估能否自动化；</li><li>实现第一版，跑一次，记录运行日志和人工审阅点。</li></ol><blockquote><p>小结：自动化的投入产出比，在于<strong>把一次成功变成无数次成功</strong>。但你永远保留最后一公里的人工确认。</p></blockquote>`,26)])])}const b=t(o,[["render",l]]);export{u as __pageData,b as default};
